const state={config:null,runs:[],reports:[],poll:null,previewTimer:null,previewRequest:0,rerunOf:null};
const metadataKeys=['CLUSTER_SIZE','ESTIMATED_CORES','MEMORY_GB','EXECUTORS','CORES_PER_EXECUTOR','INSTANCE_TYPE','SERVERLESS','ENGINE_BUILD','BENCHMARK_TYPE','DATA_SIZE','DATA_TYPE','RUN_MODE','CUSTOMER','CONFIG','TAGS','COMMENTS'];
const advancedKeys=['RAMP_UP_TIME','RAMP_UP_STEPS','QUERY_TIMEOUT','LIMIT_RESULTSET'];
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){let r;try{r=await fetch(path,{headers:{'Content-Type':'application/json'},...options})}catch(e){throw new Error('UI backend unavailable. Check that ./run_ui.sh is still running; see logs/ui.log.')}const data=await r.json();if(!r.ok)throw new Error(data.error||r.statusText);return data}
function options(items,label=x=>x,value=x=>x){return items.map(x=>`<option value="${esc(value(x))}">${esc(label(x))}</option>`).join('')}
function connectionFields(transport){return transport==='http'?`<label>mainhost<input class="new-mainhost" placeholder="host.example.com"></label><label>scheme<select class="new-scheme"><option>https</option><option>http</option></select></label><label>cluster_name<input class="new-cluster" required></label><label>CATALOG<input class="new-catalog"></label><label>SCHEMA<input class="new-schema"></label>`:`<label>CONNECTION_STRING<input class="new-url" placeholder="jdbc:e6data://host:443/…" required></label><label>DRIVER_CLASS <small>auto-filled from ENGINE</small><input class="new-driver" placeholder="Only required for Custom"></label>`}
function engineCard(i){const transport=state.config.plans.find(p=>p.id===$('plan').value)?.transport||'jdbc',stamp=new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14);return `<div class="card engine" data-transport="${transport}"><div class="card-title"><span>0${i+1}</span><div><h3>${i?'Comparison engine':'Primary engine'}</h3><p>Create the CLI properties file here, or select one already on this host</p></div></div><div class="fields"><label>Run label<input class="engine-label" value="${i?'Engine B':'Engine A'}"></label><label>ENGINE<select class="engine-kind"><option value="e6data">e6data</option><option value="databricks">Databricks</option><option value="trino">Trino</option><option value="custom">Custom</option></select></label><label>CONNECTION_FILE mode<select class="connection-mode"><option value="create">Create local profile</option><option value="existing">Use existing profile</option></select></label><label class="existing-connection hidden">CONNECTION_FILE<select class="connection"><option value="">Select a connection…</option>${options(state.config.connections,x=>x.split('/').pop())}</select></label></div><div class="new-connection"><div class="fields connection-fields"><label>Profile name<input class="new-name" value="ui_${stamp}_engine_${i+1}" required></label>${connectionFields(transport)}<label>USER<input class="new-user" autocomplete="username"></label><label>PASSWORD<input class="new-password" type="password" autocomplete="new-password"></label></div><p class="local-secret-note">Saved only under <code>connection_properties/</code> with owner-only permissions. The password is never returned to the browser after creation.</p></div></div>`}
function bindConnectionModes(){document.querySelectorAll('.connection-mode').forEach(mode=>mode.onchange=()=>{const card=mode.closest('.engine'),existing=mode.value==='existing';card.querySelector('.existing-connection').classList.toggle('hidden',!existing);card.querySelector('.new-connection').classList.toggle('hidden',existing);card.querySelector('.connection').required=existing;card.querySelectorAll('.new-connection [required]').forEach(input=>input.disabled=existing)})}
function renderEngines(){const count=$('parallel').checked?2:1;$('engines').className='engine-grid'+(count===2?' parallel':'');$('engines').innerHTML=Array.from({length:count},(_,i)=>engineCard(i)).join('');$('executionModeWrap').classList.toggle('hidden',count===1);bindConnectionModes();updatePreview()}
function planChanged(){const p=$('plan').value;document.querySelector('.profile-field').classList.toggle('hidden',!p.includes('arrivals')&&!p.includes('variable_concurrency'));document.querySelector('.param.concurrency').classList.toggle('hidden',!p.includes('concurrency')&&p!=='jdbc_run_once'&&!p.includes('variable'));document.querySelector('.param.qps').classList.toggle('hidden',p!=='jdbc_qps');document.querySelector('.param.qpm').classList.toggle('hidden',p!=='jdbc_qpm');$('durationUnit').textContent=p==='jdbc_qpm'?'minutes':'seconds';const recycle=$('RECYCLE_ON_EOF');const runOnce=p.endsWith('run_once');recycle.checked=!runOnce;recycle.disabled=runOnce;recycle.closest('label').title=runOnce?'Run-once always stops at the end of the query file':'';const profile=$('load_profile');if(p.includes('variable_concurrency')){[...profile.options].forEach(o=>o.hidden=!o.value.includes('utg_'))}else{[...profile.options].forEach(o=>o.hidden=o.value.includes('utg_'))}if(profile.selectedOptions[0]?.hidden)profile.selectedIndex=[...profile.options].findIndex(o=>!o.hidden);const transport=state.config.plans.find(plan=>plan.id===p)?.transport;if(!document.querySelector('.engine')||[...document.querySelectorAll('.engine')].some(card=>card.dataset.transport!==transport))renderEngines()}
function selectImported(kind,path){const select=$(kind==='query'?'query_file':'load_profile');if(![...select.options].some(o=>o.value===path))select.add(new Option(path,path));select.value=path;scheduleWorkloadPreview()}
async function uploadLocal(kind,file){if(!file)return;const result=await api(`/api/upload?kind=${kind}&name=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':'text/csv'},body:file});selectImported(kind,result.file)}
async function importS3(kind){const uri=prompt('Enter the complete s3://bucket/path/file.csv URI. The UI host must have AWS CLI credentials.');if(!uri)return;const result=await api('/api/import-s3',{method:'POST',body:JSON.stringify({kind,uri})});selectImported(kind,result.file)}
function applyWorkloadPreset(values){if(values.TEST_PLAN){const plan=state.config.plans.find(p=>p.path===values.TEST_PLAN||p.path.split('/').pop()===values.TEST_PLAN.split('/').pop());if(plan)$('plan').value=plan.id}if(values.QUERY_PATH)selectImported('query',values.QUERY_PATH);if(values.LOAD_PROFILE)selectImported('profile',values.LOAD_PROFILE);[...advancedKeys,'CONCURRENT_QUERY_COUNT','QPS','QPM','HOLD_PERIOD','MAX_CONCURRANCY','MAX_ERROR_PCT'].forEach(key=>{if(values[key]!==undefined&&$(key))$(key).value=values[key]});['RECYCLE_ON_EOF','RANDOM_ORDER'].forEach(key=>{if(values[key]!==undefined)$(key).checked=String(values[key]).toLowerCase()==='true'});planChanged();updatePreview()}
function applyMetadataPreset(values){metadataKeys.forEach(key=>{if($(key))$(key).value=values[key]??''});updatePreview()}
function presetValues(kind){const c=commonConfig();return kind==='workload'?{TEST_PLAN:state.config.plans.find(p=>p.id===c.plan)?.path,CONCURRENT_QUERY_COUNT:c.CONCURRENT_QUERY_COUNT,QPS:c.QPS,QPM:c.QPM,HOLD_PERIOD:c.HOLD_PERIOD,RAMP_UP_TIME:c.RAMP_UP_TIME,RAMP_UP_STEPS:c.RAMP_UP_STEPS,MAX_CONCURRANCY:c.MAX_CONCURRANCY,QUERY_TIMEOUT:c.QUERY_TIMEOUT,LIMIT_RESULTSET:c.LIMIT_RESULTSET,MAX_ERROR_PCT:c.MAX_ERROR_PCT,RECYCLE_ON_EOF:c.RECYCLE_ON_EOF,RANDOM_ORDER:c.RANDOM_ORDER,QUERY_PATH:c.query_file,LOAD_PROFILE:c.load_profile}:c.metadata}
function renderPresetControls(){const workloads=state.config.workload_presets||[],metadata=state.config.metadata_presets||[];$('workloadPreset').innerHTML='<option value="">Custom configuration</option>'+options(workloads,x=>x.name,x=>x.file);$('metadataPreset').innerHTML='<option value="">Custom metadata</option>'+options(metadata,x=>x.name,x=>x.file);$('workloadPreset').onchange=e=>{const preset=workloads.find(x=>x.file===e.target.value);if(preset)applyWorkloadPreset(preset.values)};$('metadataPreset').onchange=e=>{const preset=metadata.find(x=>x.file===e.target.value);if(preset)applyMetadataPreset(preset.values)};const inventory=[['workload',workloads],['metadata',metadata]].map(([kind,list])=>`<div class="card preset-list"><h3>${kind==='workload'?'Workload':'Metadata'} preset inventory</h3>${list.map(p=>`<div><span><strong>${esc(p.name)}</strong><small>${p.editable?'Local · editable':'Repository · read-only'}</small></span><span><button class="secondary" onclick="usePreset('${kind}','${esc(p.file)}')">Apply</button>${p.editable?`<button class="secondary" onclick="updatePreset('${kind}','${esc(p.name)}')">Update from Launch</button><button class="danger" onclick="removePreset('${kind}','${esc(p.name)}')">Delete</button>`:''}</span></div>`).join('')}</div>`).join('');$('presetInventory').innerHTML=inventory;const system=state.config.system||{},obs=state.config.observability||{},items=[['Authentication',system.auth_enabled?'Enabled':'Disabled'],['Registry backend',system.registry_backend||'sqlite'],['Registry path',system.db_path],['Artifact backend',system.artifact_backend||'local'],['Reports path',system.reports_path],['Disk free',`${system.disk_free_gb} GB`],['Retention target',`${system.retention_days} days`],['Local storage limit',`${system.max_local_report_gb} GB`],['Automatic cleanup',system.automatic_cleanup?'Enabled':'Disabled — advisory only'],['Delete after S3',system.delete_local_after_s3?'Requested; verification required':'Disabled'],['JMeter dashboard',system.generate_dashboard?'Enabled':'Disabled'],['S3 upload',system.copy_to_s3?'Enabled':'Disabled'],['S3 root',system.s3_report_path||'Not configured'],['Prometheus',obs.enabled?`Enabled · port ${obs.port}`:'Disabled'],['Prometheus URL',obs.prometheus_url||'Not configured'],['Grafana URL',obs.grafana_url||'Not configured']];$('systemSettings').innerHTML=items.map(([k,v])=>`<div><span>${esc(k)}</span><strong title="${esc(v)}">${esc(v)}</strong></div>`).join('')}
async function savePreset(kind,fromLaunch=false,fixedName='',overwrite=false){const input=$(kind==='workload'?'newWorkloadPreset':'newMetadataPreset'),status=fromLaunch?$('formError'):$(kind==='workload'?'workloadPresetStatus':'metadataPresetStatus'),suggestion=kind==='workload'?'smoke_concurrency_4':'dbr_small_warehouse',name=String(fixedName||(fromLaunch?prompt(`Name this ${kind} preset:`,suggestion)||'':input.value)).trim();if(!name){status.textContent='Preset was not saved.';return}try{const result=await api('/api/presets',{method:'POST',body:JSON.stringify({kind,name,values:presetValues(kind),overwrite})});status.textContent=`Saved locally: ${result.file}`;state.config=await api('/api/config');renderPresetControls();$(kind==='workload'?'workloadPreset':'metadataPreset').value=result.file}catch(e){status.textContent=e.message}}
function usePreset(kind,file){const list=kind==='workload'?state.config.workload_presets:state.config.metadata_presets,preset=list.find(x=>x.file===file);if(!preset)return;if(kind==='workload')applyWorkloadPreset(preset.values);else applyMetadataPreset(preset.values);document.querySelector('[data-tab="launch"]').click()}
async function updatePreset(kind,name){if(confirm(`Replace ${name} with the current Launch ${kind} values?`))await savePreset(kind,false,name,true)}
async function removePreset(kind,name){if(!confirm(`Delete local preset ${name}?`))return;await api('/api/presets/delete',{method:'POST',body:JSON.stringify({kind,name})});state.config=await api('/api/config');renderPresetControls()}
window.usePreset=usePreset;window.updatePreset=updatePreset;window.removePreset=removePreset;
function renderSystemEditor(){const s=state.config.system||{},o=state.config.observability||{},enabled=!!s.settings_write_enabled;$('systemSettingsForm').classList.toggle('hidden',!enabled);$('saveSystemSettings').classList.toggle('hidden',!enabled);$('systemSettingsStatus').textContent=enabled?'Admin-write mode enabled. Changes apply to subsequent runs.':'Read-only. Start with BENCHMARK_UI_ALLOW_SETTINGS_WRITE=true to edit.';if(!enabled)return;$('settingPrometheusEnabled').value=String(!!o.enabled);$('settingPrometheusPort').value=o.port||9270;$('settingPrometheusUrl').value=o.prometheus_url||'';$('settingGrafanaUrl').value=o.grafana_url||'';$('settingS3Enabled').value=String(!!s.copy_to_s3);$('settingS3Path').value=s.s3_report_path||'';$('settingDashboard').value=String(!!s.generate_dashboard);$('settingRetention').value=s.retention_days;$('settingMaxGb').value=s.max_local_report_gb}
async function saveSystemSettings(){const body={prometheus_enabled:$('settingPrometheusEnabled').value==='true',prometheus_port:+$('settingPrometheusPort').value,prometheus_url:$('settingPrometheusUrl').value,grafana_url:$('settingGrafanaUrl').value,copy_to_s3:$('settingS3Enabled').value==='true',s3_report_path:$('settingS3Path').value,generate_dashboard:$('settingDashboard').value==='true',retention_days:+$('settingRetention').value,max_local_report_gb:+$('settingMaxGb').value};try{await api('/api/system-settings',{method:'POST',body:JSON.stringify(body)});state.config=await api('/api/config');renderPresetControls();renderSystemEditor();$('systemSettingsStatus').textContent='System settings saved and applied to subsequent runs.'}catch(e){$('systemSettingsStatus').textContent=e.message}}
async function init(){state.config=await api('/api/config');$('plan').innerHTML=options(state.config.plans,x=>`${x.label} · ${x.path.split('/').pop()}`,x=>x.id);$('query_file').innerHTML='<option value="">Select a query dataset…</option>'+options(state.config.queries,x=>x);$('load_profile').innerHTML=options(state.config.profiles,x=>x);const obs=state.config.observability||{},system=state.config.system||{};$('GENERATE_DASHBOARD').checked=system.generate_dashboard!==false;const prometheusUrl=externalUrl(obs.prometheus_url),grafanaUrl=externalUrl(obs.grafana_url),links=[obs.enabled&&`Prometheus enabled on port ${obs.port}`,prometheusUrl&&`<a target="_blank" rel="noopener" href="${esc(prometheusUrl)}">Prometheus ↗</a>`,grafanaUrl&&`<a target="_blank" rel="noopener" href="${esc(grafanaUrl)}">Grafana dashboard ↗</a>`].filter(Boolean).join(' · '),observabilityStatus=links||'<span class="observability-disabled">Prometheus/Grafana not configured on this runner</span>';$('observabilityLinks').innerHTML=observabilityStatus;$('liveObservabilityLinks').innerHTML=observabilityStatus;renderPresetControls();$('saveWorkloadPreset').onclick=()=>savePreset('workload');$('saveMetadataPreset').onclick=()=>savePreset('metadata');$('saveWorkloadFromLaunch').onclick=()=>savePreset('workload',true);$('saveMetadataFromLaunch').onclick=()=>savePreset('metadata',true);document.querySelectorAll('[data-upload]').forEach(button=>button.onclick=()=>$(button.dataset.upload+'_upload').click());['query','profile'].forEach(kind=>$(kind+'_upload').onchange=async e=>{try{await uploadLocal(kind,e.target.files[0])}catch(err){$('formError').textContent=err.message}finally{e.target.value=''}});document.querySelectorAll('[data-s3]').forEach(button=>button.onclick=async()=>{try{await importS3(button.dataset.s3)}catch(err){$('formError').textContent=err.message}});$('exportConfig').onclick=exportEnv;$('importConfig').onchange=importEnv;document.body.addEventListener('input',updatePreview);document.body.addEventListener('change',updatePreview);planChanged();await refreshReports();await refreshRuns()}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab,.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active');if(b.dataset.tab==='compare')refreshReports();if(b.dataset.tab==='settings')renderSystemEditor()});
$('saveSystemSettings').onclick=saveSystemSettings;
$('parallel').onchange=renderEngines;$('plan').onchange=planChanged;$('refreshRuns').onclick=refreshRuns;$('latestOnly').onchange=refreshRuns;
async function connectionFor(card){if(card.querySelector('.connection-mode').value==='existing')return card.querySelector('.connection').value;const transport=card.dataset.transport;const payload={transport,name:card.querySelector('.new-name').value,user:card.querySelector('.new-user').value,password:card.querySelector('.new-password').value};if(transport==='http')Object.assign(payload,{mainhost:card.querySelector('.new-mainhost').value,scheme:card.querySelector('.new-scheme').value,cluster_name:card.querySelector('.new-cluster').value,catalog:card.querySelector('.new-catalog').value,schema:card.querySelector('.new-schema').value});else Object.assign(payload,{engine:card.querySelector('.engine-kind').value,connection_string:card.querySelector('.new-url').value,driver_class:card.querySelector('.new-driver').value});return (await api('/api/connections',{method:'POST',body:JSON.stringify(payload)})).connection}
function commonConfig(){const plan=$('plan').value,metadata={},obs=state.config?.observability||{};metadataKeys.forEach(key=>{if($(key).value.trim())metadata[key]=$(key).value.trim()});const config={plan,query_file:$('query_file').value,load_profile:$('load_profile').value,CONCURRENT_QUERY_COUNT:+$('CONCURRENT_QUERY_COUNT').value,QPS:+$('QPS').value,QPM:+$('QPM').value,HOLD_PERIOD:+$('HOLD_PERIOD').value,MAX_CONCURRANCY:+$('MAX_CONCURRANCY').value,MAX_ERROR_PCT:+$('MAX_ERROR_PCT').value,RECYCLE_ON_EOF:plan.endsWith('run_once')?false:$('RECYCLE_ON_EOF').checked,RANDOM_ORDER:$('RANDOM_ORDER').checked,GENERATE_DASHBOARD:$('GENERATE_DASHBOARD').checked,PROMETHEUS_ENABLED:!!obs.enabled,PROMETHEUS_PORT:+(obs.port||9270),metadata};if(state.rerunOf)config.rerun_of=state.rerunOf;advancedKeys.forEach(key=>config[key]=+$(key).value);return config}
function previewEnvironment(){const c=commonConfig(),card=document.querySelector('.engine');if(!card)return{};const selectedPlan=state.config?.plans.find(p=>p.id===c.plan),mode=card.querySelector('.connection-mode').value,name=card.querySelector('.new-name')?.value;return {ENGINE:card.querySelector('.engine-kind').value,CONNECTION_FILE:mode==='existing'?card.querySelector('.connection').value:`connection_properties/${name?.endsWith('_connection')?name:name+'_connection'}.properties`,TEST_PLAN:selectedPlan?.path||'',QUERY_FILE:c.query_file,LOAD_PROFILE:(c.plan.includes('arrivals')||c.plan.includes('variable_concurrency'))?c.load_profile:undefined,CONCURRENT_QUERY_COUNT:c.CONCURRENT_QUERY_COUNT,QPS:c.QPS,QPM:c.QPM,HOLD_PERIOD:c.HOLD_PERIOD,RAMP_UP_TIME:c.RAMP_UP_TIME,RAMP_UP_STEPS:c.RAMP_UP_STEPS,MAX_CONCURRANCY:c.MAX_CONCURRANCY,QUERY_TIMEOUT:c.QUERY_TIMEOUT,LIMIT_RESULTSET:c.LIMIT_RESULTSET,MAX_ERROR_PCT:c.MAX_ERROR_PCT,RECYCLE_ON_EOF:c.RECYCLE_ON_EOF,RANDOM_ORDER:c.RANDOM_ORDER,GENERATE_DASHBOARD:c.GENERATE_DASHBOARD,PROMETHEUS_ENABLED:c.PROMETHEUS_ENABLED,PROMETHEUS_PORT:c.PROMETHEUS_PORT,...c.metadata}}
function renderPlannedWorkload(p){const values=(p.values||[]).map(Number),minimum=values.length?Math.min(...values):null,maximum=p.peak??(values.length?Math.max(...values):null),duration=p.is_run_once?'Until every query-file row completes':p.duration_s===null?'Completion-time dependent':`${p.duration_s} seconds (${(p.duration_s/60).toFixed(p.duration_s%60?1:0)} min)`,total=p.expected_total===null?'Completion-rate dependent':`≈ ${p.expected_total} queries`,pattern=p.pattern||planLabel($('plan').value),cap=$('MAX_CONCURRANCY')?.value||'—',range=minimum===null?'—':minimum===maximum?`${maximum} ${p.unit}`:`${minimum}–${maximum} ${p.unit}`;$('plannedWorkload').innerHTML=`<div class="chart-title"><strong>Review requested workload before launch</strong><span>computed by backend from selected JMeter inputs</span></div><div class="plan-contract"><div><span>Test pattern</span><strong>${esc(pattern)}</strong></div><div><span>Duration</span><strong>${esc(duration)}</strong></div><div><span>Requested rate / level</span><strong>${esc(range)}</strong></div><div><span>Peak</span><strong>${fmt(maximum)} ${esc(p.unit)}</strong></div><div><span>Planned total</span><strong>${esc(total)}</strong></div><div><span>In-flight safety cap</span><strong>${esc(cap)}</strong></div></div><div class="planned-chart">${plot(values,'var(--purple-600)')}</div><p class="plan-source">Source: ${esc(p.source)} · ${p.bucket_s}s buckets</p><p class="data-note"><strong>Requested, not guaranteed:</strong> JMeter will attempt this shape. Actual fired, successful, failed and in-flight values come only from the JMeter result CSV after launch.</p>`}
async function refreshWorkloadPreview(){if(!$('plannedWorkload')||!state.config)return;const request=++state.previewRequest;try{const preview=await api('/api/workload-preview',{method:'POST',body:JSON.stringify(commonConfig())});if(request===state.previewRequest)renderPlannedWorkload(preview)}catch(e){if(request===state.previewRequest)$('plannedWorkload').innerHTML=`<div class="failure-reason"><p>${esc(e.message)}</p></div>`}}
function scheduleWorkloadPreview(){clearTimeout(state.previewTimer);state.previewTimer=setTimeout(refreshWorkloadPreview,180)}
function updatePreview(){if(!$('configPreview')||!state.config)return;const env=previewEnvironment();$('configPreview').textContent=Object.entries(env).filter(([,v])=>v!==undefined&&v!=='').map(([k,v])=>`${k}=${v}`).join('\n');scheduleWorkloadPreview()}
function envQuote(value){return '"'+String(value).replaceAll('\\','\\\\').replaceAll('"','\\"').replaceAll('$','\\$').replaceAll('`','\\`')+'"'}
function exportEnv(){const lines=Object.entries(previewEnvironment()).filter(([,v])=>v!==undefined&&v!=='').map(([k,v])=>`${k}=${envQuote(v)}`).join('\n')+'\n';const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([lines],{type:'text/plain'}));link.download='benchmark.env';link.click();URL.revokeObjectURL(link.href)}
async function importEnv(event){const file=event.target.files[0];if(!file)return;const values={};(await file.text()).split(/\r?\n/).forEach(line=>{const match=line.trim().match(/^(?:export\s+)?([A-Z][A-Z0-9_]*)=(.*)$/);if(match){let value=match[2].trim();if((value.startsWith("'")&&value.endsWith("'"))||(value.startsWith('"')&&value.endsWith('"')))value=value.slice(1,-1);values[match[1]]=value}});const plan=state.config.plans.find(p=>p.path===values.TEST_PLAN||p.path.split('/').pop()===values.TEST_PLAN?.split('/').pop());if(plan){$('plan').value=plan.id;planChanged()}if(values.QUERY_FILE)selectImported('query',values.QUERY_FILE);if(values.LOAD_PROFILE)selectImported('profile',values.LOAD_PROFILE);[...advancedKeys,'CONCURRENT_QUERY_COUNT','QPS','QPM','HOLD_PERIOD','MAX_CONCURRANCY','MAX_ERROR_PCT',...metadataKeys].forEach(key=>{if(values[key]!==undefined&&$(key))$(key).value=values[key]});['RECYCLE_ON_EOF','RANDOM_ORDER','GENERATE_DASHBOARD'].forEach(key=>{if(values[key]!==undefined)$(key).checked=values[key]==='true'});document.querySelectorAll('.engine').forEach(card=>{if(values.ENGINE)card.querySelector('.engine-kind').value=values.ENGINE;if(values.CONNECTION_FILE){const select=card.querySelector('.connection');if(![...select.options].some(o=>o.value===values.CONNECTION_FILE))select.add(new Option(values.CONNECTION_FILE.split('/').pop(),values.CONNECTION_FILE));card.querySelector('.connection-mode').value='existing';card.querySelector('.connection-mode').onchange();select.value=values.CONNECTION_FILE}});updatePreview();event.target.value=''}
$('runForm').onsubmit=async e=>{e.preventDefault();$('formError').textContent='Running preflight checks…';const common=commonConfig(),cards=[...document.querySelectorAll('.engine')];try{const connections=await Promise.all(cards.map(connectionFor));const runs=cards.map((card,i)=>({...common,label:card.querySelector('.engine-label').value,engine:card.querySelector('.engine-kind').value,connection:connections[i]}));const checks=await Promise.all(runs.map(run=>api('/api/preflight',{method:'POST',body:JSON.stringify(run)})));const warnings=checks.flatMap((check,i)=>check.warnings.map(message=>`${runs[i].label}: ${message}`));if(warnings.length&&!confirm(`Preflight warnings:\n\n${warnings.join('\n')}\n\nLaunch anyway?`)){$('formError').textContent='Launch cancelled after preflight.';return}$('formError').textContent=`Preflight passed · ${checks.map(x=>x.query_count).join(' / ')} queries`;await api('/api/runs',{method:'POST',body:JSON.stringify({runs,execution_mode:cards.length===2?$('execution_mode').value:'parallel'})});state.rerunOf=null;document.querySelector('[data-tab="live"]').click();await refreshRuns()}catch(err){$('formError').textContent=err.message}}
