async function refreshRuns(){try{const openOutputs=new Set([...document.querySelectorAll('.runner-output[open]')].map(x=>x.closest('.run-card')?.dataset.runId));state.runs=(await api('/api/runs')).sort((a,b)=>(b.started_at||0)-(a.started_at||0));$('liveCount').textContent=state.runs.filter(r=>r.status==='running').length;let visible=state.runs;if($('latestOnly').checked&&visible.length){const newest=visible[0].started_at||0;visible=visible.filter(r=>Math.abs((r.started_at||0)-newest)<10)}const el=$('liveRuns');el.className=visible.length?'run-grid':'run-grid empty';el.innerHTML=visible.length?visible.map(runCard).join(''):'No runs launched in this UI session.';openOutputs.forEach(id=>document.querySelector(`.run-card[data-run-id="${id}"] .runner-output`)?.setAttribute('open',''));if(state.runs.some(r=>['running','queued'].includes(r.status))&&!state.poll)state.poll=setInterval(refreshRuns,2000);if(!state.runs.some(r=>['running','queued'].includes(r.status))&&state.poll){clearInterval(state.poll);state.poll=null;refreshReports()}}catch(e){$('liveRuns').textContent=e.message}}
