function uniqueMeta(key,legacy=''){return [...new Set(state.reports.map(r=>metaValue(r,key,legacy)).filter(Boolean))].sort()}
const workloadKeys=['queries','test_plan'];
function compatibleReports(a,b){if(!a||!b)return true;const x=a.summary.meta||{},y=b.summary.meta||{};return workloadKeys.every(k=>x[k]===undefined||y[k]===undefined||String(x[k])===String(y[k]))}
function applyReportFilters(){const value=id=>$(id).value,includeInvalid=$('includeInvalidReports').checked,tag=value('filterTag').trim().toLowerCase(),from=value('filterDateFrom'),to=value('filterDateTo'),matches=r=>{const m=r.summary.meta||{},date=String(m.run_date||'');return(includeInvalid||r.status==='completed')&&(!value('filterBenchmark')||metaValue(r,'benchmark')===value('filterBenchmark'))&&(!value('filterRunType')||metaValue(r,'run_type')===value('filterRunType'))&&(!value('filterQueries')||metaValue(r,'queries')===value('filterQueries'))&&(!value('filterTestPlan')||metaValue(r,'test_plan')===value('filterTestPlan'))&&(!value('filterCluster')||metaValue(r,'CLUSTER_SIZE','cluster_size')===value('filterCluster'))&&(!value('filterBuild')||metaValue(r,'ENGINE_BUILD')===value('filterBuild'))&&(!tag||String(m.TAGS||'').toLowerCase().includes(tag))&&(!from||date>=from)&&(!to||date<=to)},base=state.reports.filter(matches),leftSelect=$('leftReport'),rightSelect=$('rightReport'),leftCurrent=leftSelect.value,rightCurrent=rightSelect.value,leftReports=base.filter(r=>!value('filterLeftEngine')||metaValue(r,'engine')===value('filterLeftEngine'));leftSelect.innerHTML=options(leftReports,reportLabel,x=>x.id);if(leftReports.some(r=>r.id===leftCurrent))leftSelect.value=leftCurrent;const baseline=state.reports.find(r=>r.id===leftSelect.value),rightReports=base.filter(r=>r.id!==baseline?.id&&(!value('filterRightEngine')||metaValue(r,'engine')===value('filterRightEngine'))&&(!$('compatibleOnly').checked||compatibleReports(baseline,r)));rightSelect.innerHTML=options(rightReports,r=>`${compatibleReports(baseline,r)?'[MATCH] ':'[DIFF] '}${reportLabel(r)}`,x=>x.id);if(rightReports.some(r=>r.id===rightCurrent))rightSelect.value=rightCurrent}
async function refreshReports(){state.reports=await api('/api/reports');[['filterLeftEngine','engine'],['filterRightEngine','engine'],['filterBenchmark','benchmark'],['filterRunType','run_type'],['filterQueries','queries'],['filterTestPlan','test_plan'],['filterCluster','CLUSTER_SIZE','cluster_size'],['filterBuild','ENGINE_BUILD']].forEach(([id,key,legacy])=>{const select=$(id),current=select.value,first=select.options[0].outerHTML;select.innerHTML=first+options(uniqueMeta(key,legacy));if([...select.options].some(o=>o.value===current))select.value=current;select.onchange=applyReportFilters});['includeInvalidReports','compatibleOnly','filterTag','filterDateFrom','filterDateTo','leftReport'].forEach(id=>$(id).onchange=applyReportFilters);$('filterTag').oninput=applyReportFilters;applyReportFilters()}
$('compareButton').onclick=async()=>{try{const c=await api('/api/compare',{method:'POST',body:JSON.stringify({left:$('leftReport').value,right:$('rightReport').value})});renderComparison(c)}catch(e){$('comparison').textContent=e.message}}
function renderComparison(c){
  const identity=(side,title)=>{const s=c[side]||{},m=s.meta||{},ref=c.report_identity?.[side]||{},status=String(ref.status||'completed');return `<article class="compare-identity"><header><span>${esc(title)}</span><b class="status ${esc(status)}">${esc(status)}</b></header><h3>${esc(m.engine||'Unknown engine')}</h3><p>${esc(m.cluster_size||m.CLUSTER_SIZE||'Cluster not recorded')}</p><dl><div><dt>Run</dt><dd>${esc(m.run_id||ref.id||'—')}</dd></div><div><dt>Test plan</dt><dd>${esc(m.test_plan||'—')}</dd></div><div><dt>Query dataset</dt><dd>${esc(m.queries||'—')}</dd></div><div><dt>Workload</dt><dd>${esc(m.run_type||'—')}</dd></div><div><dt>Samples</dt><dd>${fmt(s.samples)} · ${fmt(s.successful)} successful · ${fmt(s.failed)} failed</dd></div></dl></article>`};
  const identities=`<div class="compare-identities">${identity('left','Baseline')}${identity('right','Candidate')}</div>`;
  state.lastComparison=c;
  const names={planned_arrivals:'Planned arrivals',fired_samples:'Actually fired',successful:'Successful',failed:'Failed',accepted_load_pct:'Fired vs planned %',throughput_per_s:'Overall completion rate / sec',error_pct:'Error rate %',mean_ms:'Mean successful latency',p50_ms:'p50 successful latency',p95_ms:'p95 successful latency',p99_ms:'p99 successful latency',peak_in_flight:'Peak in flight',arrival_window_s:'Firing window',drain_s:'Drain time',wall_clock_s:'Total query window'},latencyKeys=new Set(['mean_ms','p50_ms','p95_ms','p99_ms']),secondsKeys=new Set(['arrival_window_s','drain_s','wall_clock_s']),neutral=new Set(['planned_arrivals','fired_samples','successful','failed','accepted_load_pct','peak_in_flight','arrival_window_s','drain_s','wall_clock_s']),display=(k,v)=>latencyKeys.has(k)?fmt(v/1000,' s'):secondsKeys.has(k)?fmt(v,' s'):fmt(v),rows=Object.entries(c.metrics).map(([k,m])=>{const good=neutral.has(k)||m.change_pct===null?'':((m.higher_is_better?m.change_pct>0:m.change_pct<0)?'better':'worse'),change=m.change_pct===null?'—':`${m.change_pct}%${m.ratio===null?'':` · ${m.ratio}×`}`;return `<tr><td>${esc(names[k]||k)}</td><td>${display(k,m.left)}</td><td>${display(k,m.right)}</td><td class="${good}">${esc(change)}</td></tr>`}).join('');
  const differences=(c.compatibility||[]).map(d=>`<tr><td>${esc(d.field)}</td><td>${esc(d.left)}</td><td>${esc(d.right)}</td><td>${esc(d.severity)}</td></tr>`).join('');
  const compatibility=differences?`<div class="compatibility-warning"><strong>Configuration differences detected</strong><p>Workload differences can invalidate a performance comparison; context differences describe the intended comparison dimension.</p><table class="compare-table"><thead><tr><th>Field</th><th>Baseline</th><th>Candidate</th><th>Type</th></tr></thead><tbody>${differences}</tbody></table></div>`:`<div class="compatibility-ok">Compatible workload signatures</div>`;
  const bias=c.survivor_bias?`<div class="comparison-alert"><strong>Survivor-bias warning</strong><p>${esc(c.survivor_bias)}</p></div>`:'';
  const leftSamples=Number(c.left?.samples||0),rightSamples=Number(c.right?.samples||0),leftSuccess=Number(c.left?.successful||0),rightSuccess=Number(c.right?.successful||0),quality=[];if(Math.min(leftSuccess,rightSuccess)<30)quality.push(`Small successful sample population (${leftSuccess} baseline, ${rightSuccess} candidate); treat percentile ratios as directional only.`);if(leftSamples!==rightSamples)quality.push(`Different fired populations (${leftSamples} versus ${rightSamples}) can invalidate throughput and latency conclusions.`);if(Number(c.left?.error_pct||0)>0||Number(c.right?.error_pct||0)>0)quality.push('At least one run contains failures; successful-only latency can be survivor-biased.');const qualityWarning=quality.length?`<div class="comparison-quality"><strong>Comparison quality warnings</strong><ul>${quality.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'';
  const reasonList=side=>(c.failure_reasons?.[side]||[]).map(x=>`<li><strong>${fmt(x.count)}×</strong> ${esc(x.message)}</li>`).join('')||'<li>None recorded</li>';
  const failures=`<details class="comparison-failures"><summary>Failure reasons from JMeter result summaries</summary><div><section><h4>Baseline</h4><ul>${reasonList('left')}</ul></section><section><h4>Candidate</h4><ul>${reasonList('right')}</ul></section></div></details>`;
  const queryRows=(c.per_query||[]).map(q=>{const a=q.left||{},b=q.right||{},ratio=q.p95_ratio,good=ratio===null?'':ratio<1?'better':ratio>1?'worse':'';return `<tr><td>${esc(q.label)}</td><td>${fmt(a.sampleCount)}</td><td>${fmt(a.errorPct,'%')}</td><td>${fmt(a.meanResTime)}</td><td>${fmt(a.pct2ResTime)}</td><td>${fmt(b.sampleCount)}</td><td>${fmt(b.errorPct,'%')}</td><td>${fmt(b.meanResTime)}</td><td>${fmt(b.pct2ResTime)}</td><td class="${good}">${ratio===null?'—':fmt(ratio,'×')}</td></tr>`}).join('');
  const perQuery=`<h3 class="comparison-title">Query-by-query · standard JMeter statistics</h3><p class="comparison-note">Latency values below come from JMeter statistics.json; no UI-side latency calculation is substituted.</p><div class="table-scroll"><table class="compare-table"><thead><tr><th>Query</th><th>Base samples</th><th>Base errors</th><th>Base mean ms</th><th>Base p95 ms</th><th>Candidate samples</th><th>Candidate errors</th><th>Candidate mean ms</th><th>Candidate p95 ms</th><th>Candidate/Base p95</th></tr></thead><tbody>${queryRows}</tbody></table></div>`;
  const visuals=['throughput_per_s','p95_ms','error_pct'].map(k=>{const m=c.metrics[k],max=Math.max(m.left,m.right,1),title=names[k];return `<article class="compare-visual"><b>${esc(title)}</b><div><span>Baseline</span><i style="width:${Math.max(2,m.left/max*100)}%"></i><em>${display(k,m.left)}</em></div><div><span>Candidate</span><i style="width:${Math.max(2,m.right/max*100)}%"></i><em>${display(k,m.right)}</em></div></article>`}).join(''),actions=`<div class="comparison-actions"><button class="secondary" onclick="exportComparison('json')">Export JSON</button><button class="secondary" onclick="exportComparison('csv')">Export CSV</button><button class="secondary" onclick="window.print()">Print</button></div>`;
  const el=$('comparison');el.className='comparison';el.innerHTML=actions+identities+qualityWarning+compatibility+bias+`<div class="compare-visuals">${visuals}</div><table class="compare-table"><thead><tr><th>Metric</th><th>Baseline</th><th>Candidate</th><th>Candidate vs baseline</th></tr></thead><tbody>${rows}</tbody></table>${failures}${perQuery}`;
}
function exportComparison(kind){const c=state.lastComparison;if(!c)return;let body,type,name;if(kind==='json'){body=JSON.stringify(c,null,2);type='application/json';name='benchmark-comparison.json'}else{const quote=v=>`"${String(v??'').replaceAll('"','""')}"`,lines=[['metric','baseline','candidate','change_pct','ratio'],...Object.entries(c.metrics).map(([k,v])=>[k,v.left,v.right,v.change_pct,v.ratio]),[],['query','baseline_samples','baseline_error_pct','baseline_mean_ms','baseline_p95_ms','candidate_samples','candidate_error_pct','candidate_mean_ms','candidate_p95_ms','candidate_baseline_p95_ratio'],...(c.per_query||[]).map(q=>[q.label,q.left?.sampleCount,q.left?.errorPct,q.left?.meanResTime,q.left?.pct2ResTime,q.right?.sampleCount,q.right?.errorPct,q.right?.meanResTime,q.right?.pct2ResTime,q.p95_ratio])];body=lines.map(row=>row.map(quote).join(',')).join('\n');type='text/csv';name='benchmark-comparison.csv'}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
window.exportComparison=exportComparison;
init().catch(e=>{$('formError').textContent=`UI initialization failed: ${e.message}`});
